CREATE TEMPORARY TABLE tmp_berechnung (
  kunde_id INT,
  umsatz DECIMAL(10,2)
);

INSERT INTO tmp_berechnung
SELECT kunde_id, SUM(betrag) FROM bestellungen GROUP BY kunde_id;

SELECT k.name, t.umsatz
FROM kunden k JOIN tmp_berechnung t ON k.id = t.kunde_id;

-- Mehrstufige Berechnung:
CREATE TEMP TABLE schritt1 AS
SELECT kunde_id, SUM(betrag) AS total
FROM bestellungen GROUP BY kunde_id;

CREATE TEMP TABLE schritt2 AS
SELECT *, NTILE(4) OVER (ORDER BY total DESC) AS quartil
FROM schritt1;

SELECT k.name, s.quartil
FROM kunden k JOIN schritt2 s ON k.id = s.kunde_id;

CREATE PROCEDURE kategorie_check (IN kat_id INT)
BEGIN
  IF (SELECT COUNT(*) FROM produkte WHERE kategorie_id = kat_id) > 0 THEN
    SELECT 'Hat Produkte';
  ELSE
    SELECT 'Leer';
  END IF;
END

CREATE PROCEDURE jaehrliche_statistik (IN jahr INT)
BEGIN
  SELECT COUNT(*) INTO @anzahl FROM bestellungen WHERE YEAR(datum) = jahr;
  SELECT SUM(betrag) INTO @gesamt FROM bestellungen WHERE YEAR(datum) = jahr;
  SELECT @anzahl AS anzahl, @gesamt AS gesamtumsatz;
END

