CREATE PROCEDURE preis_setzen (IN p_id INT, IN neuer_preis DECIMAL)
BEGIN
  IF neuer_preis < 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Preis darf nicht negativ sein';
  END IF;
  UPDATE produkte SET preis = neuer_preis WHERE id = p_id;
END

