CREATE PROCEDURE sichere_ueberweisung (IN von INT, IN zu INT, IN betrag DECIMAL)
BEGIN
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN ROLLBACK; END;

  START TRANSACTION;
  UPDATE konten SET saldo = saldo - betrag WHERE id = von;
  UPDATE konten SET saldo = saldo + betrag WHERE id = zu;
  COMMIT;
END

