CREATE PROCEDURE berechne_provision ()
BEGIN
  DECLARE fertig INT DEFAULT 0;
  DECLARE v_id INT;
  DECLARE v_umsatz DECIMAL;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET fertig = 1;
  DECLARE cur CURSOR FOR
    SELECT id, umsatz FROM mitarbeiter;
  OPEN cur;
  loop_start: LOOP
    FETCH cur INTO v_id, v_umsatz;
    IF fertig THEN LEAVE loop_start; END IF;
    UPDATE mitarbeiter SET provision = v_umsatz * 0.1 WHERE id = v_id;
  END LOOP;
  CLOSE cur;
END

